Eigen::MatrixXd matrix(std::ifstream&f){auto r=count(f),c=count(f);need(r<=20000&&c<=144&&r*c<=3000000,"fixture bounded matrix");Eigen::MatrixXd a(r,c);for(auto i=0ULL;i<r;++i)for(auto j=0ULL;j<c;++j){f.read(reinterpret_cast<char*>(&a(i,j)),8);need(bool(f),"whole fixture matrix");}need(a.allFinite(),"finite matrix");return a;}
